import{_ as a,a0 as n,w as l,s as u,I as r,x as e,a1 as o,A as i,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Brave 瀏覽器中使用畫中畫模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Brave 瀏覽器中使用畫中畫模式 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Brave 瀏覽器中使用畫中畫模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Brave 瀏覽器中使用畫中畫模式 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220929 How to Use Picture in Picture Mode in Brave Browser","title":"如何在 Brave 瀏覽器中使用畫中畫模式","tag":"202210","desc":""},"relativePath":"202210/20220929 How to Use Picture in Picture Mode in Brave Browser.md","filePath":"[post].md"}'),d={name:"202210/20220929 How to Use Picture in Picture Mode in Brave Browser.md"};function m(f,t,v,b,g,B){const p=n("Link");return l(),u("div",null,[t[21]||(t[21]=r("h1",{id:"如何在-brave-瀏覽器中使用畫中畫模式",tabindex:"-1"},[e("如何在 Brave 瀏覽器中使用畫中畫模式 "),r("a",{class:"header-anchor",href:"#如何在-brave-瀏覽器中使用畫中畫模式","aria-label":"Permalink to “如何在 Brave 瀏覽器中使用畫中畫模式”"},"​")],-1)),t[22]||(t[22]=r("p",null,[r("img",{src:"https://img.linux.net.cn/data/attachment/album/202210/13/003034agqsflug771cl3uj.jpg",alt:""})],-1)),r("blockquote",null,[r("p",null,[t[1]||(t[1]=e("Brave 是一款出色的類似於 Chrome，但可 ",-1)),o(p,{href:"https://itsfoss.com/open-source-browsers-linux/"},{default:i(()=>[...t[0]||(t[0]=[e("替代 Chrome 的網絡瀏覽器",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))])]),r("p",null,[o(p,{href:"https://itsfoss.com/brave-vs-firefox/"},{default:i(()=>[...t[3]||(t[3]=[e("Firefox 和 Brave",-1)])]),_:1}),t[4]||(t[4]=e(" 是我喜歡在 Linux 系統上使用的兩種瀏覽器。兩者都有不同的優勢。",-1))]),t[23]||(t[23]=s('<p>Firefox 比 Brave 做得更好的一件事就是畫中畫（PIP）模式，它適用於 YouTube、Netflix 和大多數流媒體網站。</p><p>Brave 也有畫中畫模式，但它是如此隱藏，以至於你覺得它根本沒有 PIP 支持。</p><p>內置畫中畫適用於某些網站（如 YouTube），但可能不適用於其他網站（如 Prime Video）。不用擔心！你可以為此使用專用擴展。</p><p>讓我在本教程中展示這兩種方法。</p><h3 id="方法-1-在視頻上雙擊右鍵" tabindex="-1">方法 1：在視頻上雙擊右鍵 <a class="header-anchor" href="#方法-1-在視頻上雙擊右鍵" aria-label="Permalink to “方法 1：在視頻上雙擊右鍵”">​</a></h3><p><strong>技巧是依次單擊兩次右鍵，你應該會看到畫中畫模式選項。</strong></p><p>讓我通過一個例子來説明這一點。在 Brave 中播放 YouTube 視頻。現在右鍵單擊視頻。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/getting-picture-in-picture-in-brave-1.webp" alt="第一次右鍵單擊後將光標從上下文菜單稍微移開"></p><p>再次右鍵單擊。它應該在視頻上，但不在上一個上下文菜單上，而在視頻的其他地方。</p><p>現在你應該看到另一個帶有畫中畫選項的上下文菜單。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/getting-picture-in-picture-in-brave-2.webp" alt="你應該在第二次右鍵單擊中看到畫中畫選項"></p><p>選擇畫中畫，視頻將從窗口中彈出。你可以將其移動到瀏覽器中的任何位置。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/brave-picture-in-picture-youtube.webp" alt="Brave 瀏覽器畫中畫模式"></p><p>當你使用其他應用時，你還可以讓它在屏幕上的任何位置播放。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/brave-playing-picture-in-picture-mode-on-screen.webp" alt="Brave 在畫中畫模式中播放影片"></p><p>在最近的 Brave 版本中，你可以根據自己的喜好調整彈出窗口的大小。</p><p>我不明白為什麼 Brave 把它隱藏成這樣。為什麼不突出它？</p><p>無論如何，這適用於 YouTube 等網站，但可能不適用於 Prime 視頻。如果你願意，你可以安裝一個擴展。</p><h3 id="方法-2-使用畫中畫擴展" tabindex="-1">方法 2：使用畫中畫擴展 <a class="header-anchor" href="#方法-2-使用畫中畫擴展" aria-label="Permalink to “方法 2：使用畫中畫擴展”">​</a></h3><p>谷歌提供了一個官方插件，可讓你在谷歌 Chrome 中獲得畫中畫功能。由於 Brave 基於 Chromium，你可以在 Brave 中使用相同的擴展。</p>',20)),r("blockquote",null,[r("p",null,[r("strong",null,[o(p,{href:"https://chrome.google.com/webstore/detail/picture-in-picture-extens/hkgfoiooedgoejojocmhlaklaeopbecg/related?hl=en-US"},{default:i(()=>[...t[5]||(t[5]=[e("畫中畫擴展",-1)])]),_:1})])])]),t[24]||(t[24]=s('<p>進入擴展頁面並點擊 “<ruby>添加到 Brave<rt>Add to Brave</rt></ruby>” 按鈕。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/picture-in-picture-extension-google-chrome-web.png" alt="為 Brave 添加畫中畫擴展"></p><p>當你單擊它時，它會提示添加擴展的選項。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/add-picture-in-picture-extension-to-brave.webp" alt="添加擴展"></p><p>添加擴展後，你應該會在瀏覽器的右上角看到它。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/picture-in-picture-extension.png" alt="使用畫中畫擴展"></p><p>播放視頻時，單擊該擴展圖標，視頻應該會彈出。</p><h3 id="你能在-brave-中啓用-pip-模式嗎" tabindex="-1">你能在 Brave 中啓用 PIP 模式嗎？ <a class="header-anchor" href="#你能在-brave-中啓用-pip-模式嗎" aria-label="Permalink to “你能在 Brave 中啓用 PIP 模式嗎？”">​</a></h3><p>畫中畫模式已成為休閒流媒體消費的必備功能。我覺得奇怪的是，Brave 和其他瀏覽器沒有足夠重視它。 Firefox 處理得很好。</p><p>我希望這個快速的小技巧可以幫助你在 Brave 瀏覽器中獲得 PIP 體驗。你更喜歡這兩種方法中的哪一種？右鍵單擊還是擴展？</p><hr>',11)),r("p",null,[t[7]||(t[7]=e("via: ",-1)),o(p,{href:"https://itsfoss.com/picture-in-picture-brave/"},{default:i(()=>[...t[6]||(t[6]=[e("https://itsfoss.com/picture-in-picture-brave/",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=e("作者：",-1)),o(p,{href:"https://itsfoss.com/"},{default:i(()=>[...t[8]||(t[8]=[e("Abhishek Prakash",-1)])]),_:1}),t[13]||(t[13]=e(" 選題：",-1)),o(p,{href:"https://github.com/lkxed"},{default:i(()=>[...t[9]||(t[9]=[e("lkxed",-1)])]),_:1}),t[14]||(t[14]=e(" 譯者：",-1)),o(p,{href:"https://github.com/geekpi"},{default:i(()=>[...t[10]||(t[10]=[e("geekpi",-1)])]),_:1}),t[15]||(t[15]=e(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:i(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[18]||(t[18]=e("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原創編譯，",-1)),o(p,{href:"https://linux.cn/"},{default:i(()=>[...t[17]||(t[17]=[e("Linux中國",-1)])]),_:1}),t[20]||(t[20]=e(" 榮譽推出",-1))])])}const w=a(d,[["render",m]]);export{x as __pageData,w as default};
